import imageData from "@/data/images.json";
// catalog.json is generated by scripts/build-catalog.mjs (premium analyses without numbers) – never import reports.json
// here: this module is bundled into the browser JS.
import catalog from "@/data/catalog.json";

export type Report = {
  slug: string;
  file: string;
  name: string;
  brand: string;
  model: string;
  kind: "model" | "comparison";
  date: string;
  summary: string;
  ads: number | null;
  median: string | null;
  r2: string | null;
  history?: {
    as_of: string;
    updated_at: string;
    last_observed_at: string | null;
    active_count: number;
    inactive_count: number;
    unverified_count: number;
    new_count: number;
    price_changed_count: number;
    total_count: number;
    coverage: "partial";
  };
};

export type Photo = { src: string; author: string; license: string; source: string; file?: string };

export const reports = catalog.reports as Report[];
const images = imageData as Record<string, Partial<Photo>>;

/** The model's photo; a comparison gets the photos of the models it compares. */
export const photosFor = (r: Report): Photo[] =>
  (r.kind === "model"
    ? [images[r.slug]]
    : reports
        .filter((m) => m.kind === "model" && r.name.toLowerCase().includes(m.model.split(" ")[0].toLowerCase()))
        .map((m) => images[m.slug])
  ).filter((p): p is Photo => Boolean(p?.src));

export const allPhotos = () =>
  reports.filter((r) => r.kind === "model").flatMap((r) => photosFor(r).map((p) => ({ ...p, name: r.name })));

export const getReport = (slug: string) => reports.find((r) => r.slug === slug);

export const formatDate = (iso: string) => {
  const [y, m, d] = iso.split("-").map(Number);
  return `${d}. ${m}. ${y}`;
};

export const formatNum = (n: number) => n.toLocaleString("sk-SK").replace(/ /g, " ");

export const totals = () => catalog.totals;

export type SamplePick = { title: string; url: string; facts: string; price: string; fair: string; discount: string | null };
/** Real recommended offers of the free sample analysis on the home page (scripts/build-catalog.mjs). */
export const sample = catalog.sample as { slug: string; picks: SamplePick[] };
